from pathlib import Path
import base64,json,os,re,subprocess,sys,tempfile
ROOT=Path.home()
FRONT=ROOT/'ASTRA-Frontend-latest'
BACK=ROOT/'ASTRA-Backend-latest'
contents=json.loads(base64.b64decode(''))
replacements=json.loads(base64.b64decode(''))
original={ROOT/p:(ROOT/p).read_text(encoding='utf-8-sig') if (ROOT/p).exists() else None for p in contents}
updated={ROOT/p:text for p,text in contents.items()}
for change in replacements:
    p=ROOT/change['path']
    original[p]=p.read_text(encoding='utf-8-sig')
    source=original[p]
    if change['newText'] not in source:
        if source.count(change['old'])!=1:raise SystemExit('STOP: profile identity differs in '+change['path']+'. No files changed.')
        source=source.replace(change['old'],change['newText'],1)
    if change['importLine'] not in source:source=change['importLine']+source
    updated[p]=source
p=BACK/'FeatureApis.cs'
original[p]=p.read_text(encoding='utf-8-sig')
source=original[p]
if '        MapProfile(api);' not in source:
    if source.count('        MapTicketQa(api);')!=1:raise SystemExit('STOP: API mappings differ. No files changed.')
    source=source.replace('        MapTicketQa(api);','        MapTicketQa(api);\n        MapProfile(api);',1)
updated[p]=source
paths=list(updated)
print('Profile update: self-only employee details, resolution metrics, QA average and photo upload.',flush=True)
print('No database migration or sample profile data will be written.',flush=True)
if '--apply' not in sys.argv:raise SystemExit('REVIEW ONLY: no files changed.')
# Confirm a single owned Development preview before touching source.
listeners = subprocess.check_output(['ss','-ltnp','sport = :5200'], text=True)
pids = set(re.findall(r'pid=(\d+)', listeners))
if len(pids) != 1: raise SystemExit('STOP: expected one existing backend on port 5200.')
proc = Path('/proc') / pids.pop()
if proc.stat().st_uid != os.getuid() or (proc/'cwd').resolve() != BACK.resolve():
    raise SystemExit('STOP: backend owner or project folder differs.')
env = dict(part.split(b'=',1) for part in (proc/'environ').read_bytes().split(b'\0') if b'=' in part)
env = {os.fsdecode(k):os.fsdecode(v) for k,v in env.items()}
if (env.get('DOTNET_ENVIRONMENT') or env.get('ASPNETCORE_ENVIRONMENT')) != 'Development':
    raise SystemExit('STOP: only the Development preview can be updated.')
if env.get('ASPNETCORE_URLS') != 'http://127.0.0.1:5200':
    raise SystemExit('STOP: expected loopback-only preview.')
helper = BACK/'local-maintenance/restart-ticket-preview.py'
if not helper.is_file(): raise SystemExit('STOP: project restart helper is missing.')
try:
    for p in paths:
        if updated[p] != original[p]:
            p.parent.mkdir(parents=True,exist_ok=True)
            p.write_text(updated[p], encoding='utf-8')
    subprocess.run(['npm','run','build'], cwd=FRONT, check=True)
    build = tempfile.mkdtemp(prefix='astra-ticket-ready.', dir='/tmp')
    subprocess.run(['dotnet','build','Astra.Api.csproj','-o',build], cwd=BACK, check=True)
    subprocess.run(['python3',str(helper),build], cwd=BACK, check=True)
except BaseException:
    for p in paths:
        if original[p] is None:
            if p.exists():p.unlink()
        elif updated[p] != original[p]:p.write_text(original[p], encoding='utf-8')
    print('Update failed; original source restored from memory. No backup files created.', flush=True)
    raise

# Verify the live database queries without creating sample data.
with tempfile.TemporaryDirectory(prefix='.profile-check-',dir=BACK/'local-maintenance') as directory:
    folder=Path(directory)
    project='<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup><ItemGroup><ProjectReference Include="'+str(BACK/'Astra.Api.csproj')+'" /></ItemGroup></Project>'
    (folder/'Check.csproj').write_text(project)
    (folder/'Program.cs').write_bytes(base64.b64decode(''))
    subprocess.run(['dotnet','build',str(folder/'Check.csproj'),'--ignore-failed-sources','-p:NuGetAudit=false'],cwd=BACK,check=True)
    subprocess.run(['dotnet',str(folder/'bin/Debug/net10.0/Check.dll')],cwd=BACK,env=env,check=True)
print('SUCCESS: Ubuntu employee profiles are healthy. Click your name or avatar.', flush=True)
